static int passed,failed;static wchar_t repo[32768],linux_repo[32768],conflict[32768];
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL %d %s (error %lu)\n",__LINE__,label,(unsigned long)GetLastError());}}while(0)
static int text_is(const diff_result *r,int side,const wchar_t *s){return r->mode==DIFF_TEXT&&r->doc[side].data.text&&!wcscmp(r->doc[side].data.text,s);}
static void test_git_status_windows_and_parser(void){git_result r={0};CHECK("actual Windows Git status",!git_status_read(repo,0,0,NULL,&r));CHECK("branch is main",!wcscmp(r.model.branch,L"main")&&git_oid_valid(r.model.oid));CHECK("local upstream counts parsed",r.model.tracking&&!r.model.ahead&&!r.model.behind&&!wcscmp(r.model.upstream,L"upstream"));const git_entry *both=git_find(&r.model,L"both.md"),*rename=git_find(&r.model,L"renamed.txt"),*deleted=git_find(&r.model,L"deleted.txt"),*fresh=git_find(&r.model,L"fresh space #%.txt");CHECK("staged and unstaged tracked independently",both&&both->meta.x=='M'&&both->meta.y=='M');CHECK("rename original retained",rename&&rename->original&&!wcscmp(rename->original,L"rename-old.txt")&&rename->meta.x=='R');CHECK("deletion and untracked names retained",deleted&&deleted->meta.y=='D'&&fresh&&fresh->meta.kind=='?');CHECK("ignored files absent",!git_find(&r.model,L"ignored.log"));wchar_t mark[4];CHECK("file badges use cached XY",git_badge(&r.model,repo,L"both.md",0,mark)&&!wcscmp(mark,L"MM"));CHECK("folder badges aggregate descendants",git_badge(&r.model,repo,L"nested",1,mark)&&!wcscmp(mark,L"*"));CHECK("clean and outside rows have no badge",!git_badge(&r.model,repo,L".gitignore",0,mark)&&!git_badge(&r.model,L"C:\\unrelated",L"both.md",0,mark));git_model m={0};CHECK("missing branch headers cannot report clean",git_parse_status(&m,repo,NULL,0,0)==ERROR_INVALID_DATA);CHECK("unterminated records rejected",git_parse_status(&m,repo,(uint8_t*)"? a",3,0)==ERROR_INVALID_DATA);const char bad[]="# branch.oid (initial)\0# branch.head main\0? ../escape\0";CHECK("traversal records rejected",git_parse_status(&m,repo,(uint8_t*)bad,sizeof bad-1,0)==ERROR_INVALID_DATA);CHECK("path and OID argument guards",!git_path_safe(L"a:stream")&&!git_path_safe(L"..\\x")&&!git_oid_valid("HEAD:secret")&&git_path_safe(L"a b\\file.md"));git_model_free(&m);git_result_free(&r);}
static void test_git_diff_staged_unstaged_deletion_binary(void){git_result r={0};git_status_read(repo,0,0,NULL,&r);const git_entry *both=git_find(&r.model,L"both.md");CHECK("diff source available",both!=NULL);if(both){git_diff_open q={.staged=1,.meta=both->meta};diff_result d={0};CHECK("staged diff is HEAD versus index",!git_diff_read(repo,both->path,&q,NULL,&d)&&text_is(&d,0,L"base\n")&&text_is(&d,1,L"staged\n")&&d.hunks==1);diff_free(&d);q.staged=0;CHECK("unstaged diff is index versus working file",!git_diff_read(repo,both->path,&q,NULL,&d)&&text_is(&d,0,L"staged\n")&&text_is(&d,1,L"working\n"));diff_free(&d);HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);CHECK("diff cancellation cannot become equality",git_diff_read(repo,both->path,&q,cancel,&d)==ERROR_CANCELLED);diff_free(&d);CloseHandle(cancel);CHECK("diff traversal refused",git_diff_read(repo,L"..\\outside",&q,NULL,&d)!=0);diff_free(&d);}
 const git_entry *e=git_find(&r.model,L"deleted.txt");if(e){git_diff_open q={.meta=e->meta};diff_result d={0};CHECK("deleted working file is an empty right side",!git_diff_read(repo,e->path,&q,NULL,&d)&&d.doc[0].bytes==8&&d.doc[1].bytes==0&&!d.bytes_equal);diff_free(&d);}e=git_find(&r.model,L"binary.bin");if(e){git_diff_open q={.meta=e->meta};diff_result d={0};CHECK("binary Git diff has complete byte summary",!git_diff_read(repo,e->path,&q,NULL,&d)&&d.mode==DIFF_BINARY&&!d.bytes_equal&&d.doc[0].bytes==3&&d.doc[1].bytes==3);diff_free(&d);}git_result_free(&r);}
static int recreated_file(const wchar_t *path,const char *text){HANDLE h=CreateFileW(path,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(h==INVALID_HANDLE_VALUE)return 0;DWORD n=0,want=(DWORD)strlen(text);int ok=WriteFile(h,text,want,&n,NULL)&&n==want;CloseHandle(h);return ok;}
static void recreated_working_cases(const wchar_t *root,int native){
 printf("Recreated working-side provider: %s\n",native?"native Linux":"Windows");git_result status={0};DWORD error=git_status_read(root,native,0,NULL,&status);CHECK("deletion status captured before working-file recreation",!error);if(error)return;
 const git_entry *deleted=git_find(&status.model,L"deleted.txt"),*empty=git_find(&status.model,L"empty-deleted.txt");CHECK("captured regular and empty-blob deletions both have zero working mode",deleted&&empty&&deleted->meta.y=='D'&&empty->meta.y=='D'&&!deleted->meta.mode[2]&&!empty->meta.mode[2]);if(!deleted||!empty){git_result_free(&status);return;}
 git_diff_open q={.wsl=(uint32_t)native,.meta=deleted->meta};diff_result d={0};wchar_t path[32768];swprintf(path,32768,L"%ls\\deleted.txt",status.model.root);
 CHECK("index-identical working file recreated after capture",recreated_file(path,"deleted\n"));CHECK("retained deletion reads identical current bytes",!git_diff_read(status.model.root,deleted->path,&q,NULL,&d)&&d.bytes_equal&&text_is(&d,0,L"deleted\n")&&text_is(&d,1,L"deleted\n"));diff_free(&d);
 CHECK("owned recreation removed before replacement",DeleteFileW(path));CHECK("different current working bytes recreated",recreated_file(path,"recreated\n"));CHECK("retained deletion reads different current bytes",!git_diff_read(status.model.root,deleted->path,&q,NULL,&d)&&!d.bytes_equal&&text_is(&d,0,L"deleted\n")&&text_is(&d,1,L"recreated\n"));diff_free(&d);
 q.staged=1;CHECK("working recreation does not change captured staged blob sides",!git_diff_read(status.model.root,deleted->path,&q,NULL,&d)&&d.bytes_equal&&text_is(&d,0,L"deleted\n")&&text_is(&d,1,L"deleted\n"));diff_free(&d);q.staged=0;
 HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);CHECK("pre-cancelled retained deletion cannot report equality",git_diff_read(status.model.root,deleted->path,&q,cancel,&d)==ERROR_CANCELLED&&d.error==ERROR_CANCELLED);diff_free(&d);CloseHandle(cancel);
 if(!native){HANDLE locked=CreateFileW(path,GENERIC_WRITE,0,NULL,OPEN_EXISTING,0,NULL);CHECK("owned recreated file locked exclusively",locked!=INVALID_HANDLE_VALUE);error=git_diff_read(status.model.root,deleted->path,&q,NULL,&d);CHECK("sharing failure on recreated file remains an error",error==ERROR_SHARING_VIOLATION&&d.error==error&&d.error_side==1&&!d.bytes_equal);diff_free(&d);if(locked!=INVALID_HANDLE_VALUE)CloseHandle(locked);}
 CHECK("regular recreation removed before type-change probe",DeleteFileW(path));CHECK("unsupported directory created at captured deleted path",CreateDirectoryW(path,NULL));error=git_diff_read(status.model.root,deleted->path,&q,NULL,&d);CHECK("recreated unsupported type is refused instead of synthesized empty",error&&d.error==error&&d.error_side==1&&!d.bytes_equal);diff_free(&d);CHECK("owned type-change fixture removed",RemoveDirectoryW(path));
 HANDLE large=CreateFileW(path,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);LARGE_INTEGER end={.QuadPart=GR_BLOB_LIMIT+1};CHECK("owned over-limit recreation created",large!=INVALID_HANDLE_VALUE&&SetFilePointerEx(large,end,NULL,FILE_BEGIN)&&SetEndOfFile(large));if(large!=INVALID_HANDLE_VALUE)CloseHandle(large);CHECK("recreated files retain the existing source-size bound",git_diff_read(status.model.root,deleted->path,&q,NULL,&d)==ERROR_BUFFER_OVERFLOW&&d.error==ERROR_BUFFER_OVERFLOW&&!d.bytes_equal);diff_free(&d);CHECK("over-limit recreation removed",DeleteFileW(path));
 CHECK("still-absent captured deletion remains an empty working side",!git_diff_read(status.model.root,deleted->path,&q,NULL,&d)&&!d.bytes_equal&&d.doc[0].bytes==8&&d.doc[1].bytes==0);diff_free(&d);
 swprintf(path,32768,L"%ls\\empty-deleted.txt",status.model.root);q.meta=empty->meta;CHECK("nonempty working file recreated over an empty index blob",recreated_file(path,"new bytes\n"));CHECK("empty index cannot falsely equal nonempty recreated content",!git_diff_read(status.model.root,empty->path,&q,NULL,&d)&&!d.bytes_equal&&d.doc[0].bytes==0&&text_is(&d,1,L"new bytes\n"));diff_free(&d);CHECK("empty-blob recreation removed",DeleteFileW(path));CHECK("actually absent working file may equal an empty captured index",!git_diff_read(status.model.root,empty->path,&q,NULL,&d)&&d.bytes_equal&&!d.doc[0].bytes&&!d.doc[1].bytes);diff_free(&d);git_result_free(&status);
}
static void test_git_windows_recreated_working_files(void){recreated_working_cases(repo,0);}
static void test_git_native_recreated_working_files(void){recreated_working_cases(linux_repo,1);}

static void test_git_native_linux_raw_names_and_worktrees(void){git_result r={0};DWORD native_error=git_status_read(linux_repo,1,0,NULL,&r);if(native_error)printf("native diagnostic: error=%lu Git exit=%lu\n",(unsigned long)native_error,(unsigned long)r.code);CHECK("native Linux Git status",!native_error&&r.model.native);CHECK("Linux reserved and raw names decoded",git_find(&r.model,L"a\uf03ab.txt")&&git_find(&r.model,L"raw-\xdcff"));wchar_t alias[32768],mark[4];const wchar_t *tail=wcschr(linux_repo+2,L'\\');swprintf(alias,32768,L"\\\\wsl$%ls",tail?tail:L"");CHECK("cached badges support both WSL UNC aliases",git_badge(&r.model,alias,L"both.md",0,mark)&&!wcscmp(mark,L"MM"));const git_entry *e=git_find(&r.model,L"both.md");if(e){git_diff_open q={.wsl=1,.meta=e->meta};diff_result d={0};CHECK("native working diff bytes",!git_diff_read(r.model.root,e->path,&q,NULL,&d)&&text_is(&d,0,L"staged\n")&&text_is(&d,1,L"working\n"));diff_free(&d);q.staged=1;CHECK("native immutable staged blobs",!git_diff_read(r.model.root,e->path,&q,NULL,&d)&&text_is(&d,0,L"base\n")&&text_is(&d,1,L"staged\n"));diff_free(&d);q.staged=0;q.meta.mode[2]=0120000;CHECK("symlink diffs are explicitly unsupported",git_diff_read(r.model.root,e->path,&q,NULL,&d)==ERROR_NOT_SUPPORTED);diff_free(&d);}git_result_free(&r);CHECK("disabled Linux never falls back to Windows provider",git_status_read(linux_repo,0,0,NULL,&r)==ERROR_NOT_SUPPORTED);git_result_free(&r);wchar_t path[32768];DWORD n=GetEnvironmentVariableW(L"OPENPILOT_GIT_WORKTREE",path,32768);CHECK("owned linked worktree supplied",n&&n<32768);if(n&&n<32768){CHECK("linked worktree recognized with gitfile metadata",!git_status_read(path,1,0,NULL,&r)&&!wcscmp(r.model.branch,L"linked"));git_result_free(&r);}n=GetEnvironmentVariableW(L"OPENPILOT_GIT_INITIAL",path,32768);CHECK("owned unborn repository supplied",n&&n<32768);if(n&&n<32768){CHECK("unborn branch shown truthfully",!git_status_read(path,1,0,NULL,&r)&&!strcmp(r.model.oid,"(initial)"));git_result_free(&r);}}
static void test_git_conflicts_errors_and_environment(void){git_result r={0};CHECK("conflicted repo status succeeds",!git_status_read(conflict,1,0,NULL,&r));const git_entry *e=git_find(&r.model,L"conflict.txt");CHECK("unmerged entry remains a conflict",e&&e->meta.kind=='u'&&e->meta.x=='U'&&e->meta.y=='U');git_result_free(&r);wchar_t nested[32768];swprintf(nested,32768,L"%ls\\nested",repo);CHECK("subfolder discovers full repository root",!git_status_read(nested,0,0,NULL,&r)&&git_find(&r.model,L"both.md"));git_result_free(&r);wchar_t old[32768];DWORD had=GetEnvironmentVariableW(L"GIT_DIR",old,32768);SetEnvironmentVariableW(L"GIT_DIR",L"C:\\nonexistent-openpilot-git-override");CHECK("inherited Git routing cannot retarget request",!git_status_read(repo,0,0,NULL,&r)&&git_find(&r.model,L"both.md"));SetEnvironmentVariableW(L"GIT_DIR",had?old:NULL);git_result_free(&r);HANDLE cancel=CreateEventW(NULL,TRUE,TRUE,NULL);CHECK("pre-cancelled status returns stopped",git_status_read(repo,0,0,cancel,&r)==ERROR_CANCELLED);git_result_free(&r);CloseHandle(cancel);CHECK("invalid repository has no clean snapshot",git_status_read(L"C:\\nonexistent-openpilot-git-repo",0,0,NULL,&r)!=0&&!r.model.root&&!r.model.count);git_result_free(&r);}
static void join_panel(void){uint64_t end=GetTickCount64()+30000;while(A.thread&&GetTickCount64()<end){Sleep(5);tick();}}
static void test_git_panel_filters_lifecycle_and_pixels(void){A.dpi=96;A.shown=1;A.selected=-1;A.out=CreateFileW(L"NUL",GENERIC_WRITE,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,0,NULL);A.cancel=CreateEventW(NULL,TRUE,FALSE,NULL);fonts();HANDLE section=CreateFileMappingW(INVALID_HANDLE_VALUE,NULL,PAGE_READWRITE,0,520*800*8,NULL);CHECK("real status panel mapping",map(section,520,800));git_open q={.session=11};queue(&q,repo);join_panel();CHECK("worker publishes status snapshot",!A.thread&&A.ready&&!A.result.error&&A.count>A.result.model.count);A.request.wsl=1;A.run_wsl=1;struct {panelp_head h;uint32_t enabled;} policy={{PANELP_GIT_WSL_POLICY,4},0};on_host((msg*)&policy);CHECK("policy intake preserves completed Windows results and captured worker policy",!A.request.wsl&&!A.queued_request.wsl&&A.run_wsl==1&&A.ready&&!A.result.error);begin();join_panel();CHECK("next Windows worker captures disabled WSL policy",!A.thread&&!A.run_wsl&&A.ready&&!A.result.error);uint32_t gen=A.generation;queue(&q,repo);CHECK("replayed roots preserve cached snapshot",A.generation==gen&&!A.thread);activate(9);int good=A.count>0;for(uint32_t i=0;i<A.count;i++)if(A.rows[i].section!=0)good=0;CHECK("Staged filter contains only staged rows",good);activate(11);good=A.count>0;for(uint32_t i=0;i<A.count;i++)if(A.rows[i].section!=2)good=0;CHECK("Untracked filter contains only untracked rows",good);activate(8);A.focus=0;input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_DOWN});CHECK("keyboard selects next row",A.selected==1);A.shown=0;tick();CHECK("hide retains helper model",A.ready&&A.result.model.count);A.shown=1;paint();int different=0;uint32_t *pixels=A.pixels;for(int i=0;i<A.w*A.h;i++)if((pixels[i]&0xffffff)!=(pixels[0]&0xffffff)){different=1;break;}CHECK("real panel paints rows and controls",different);wchar_t shot[32768];if(GetEnvironmentVariableW(L"OPENPILOT_GIT_SCREENSHOT",shot,32768)){BITMAPINFOHEADER bi={sizeof bi,A.w,-A.h,1,32,BI_RGB};BITMAPFILEHEADER fh={.bfType=0x4d42,.bfSize=(DWORD)(sizeof fh+sizeof bi+A.w*A.h*4),.bfOffBits=sizeof fh+sizeof bi};HANDLE f=CreateFileW(shot,GENERIC_WRITE,0,NULL,CREATE_NEW,0,NULL);if(f!=INVALID_HANDLE_VALUE){io(f,&fh,sizeof fh,1);io(f,&bi,sizeof bi,1);io(f,A.pixels,A.w*A.h*4,1);CloseHandle(f);}}
 input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_F5});CHECK("refresh invalidates actions and increments generation",A.thread&&!A.ready&&A.generation!=gen);q.session=12;queue(&q,repo);join_panel();CHECK("root supersession joins before adoption",A.ready&&!A.thread&&A.request.session==12&&!A.result.error);input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_F5});input(&(panelp_input){.msg=WM_KEYDOWN,.wparam=VK_ESCAPE});join_panel();CHECK("Escape stops current request",!A.thread&&A.result.error==ERROR_CANCELLED);git_result_free(&A.result);git_result_free(&A.work);free(A.rows);free(A.root);free(A.queued);CloseHandle(A.out);CloseHandle(A.cancel);UnmapViewOfFile(A.shared);CloseHandle(A.section);SelectObject(A.dc,A.original);DeleteObject(A.bitmap);DeleteDC(A.dc);DeleteObject(A.font);DeleteObject(A.bold);memset(&A,0,sizeof A);}
int wmain(int argc,wchar_t **argv){setvbuf(stdout,NULL,_IONBF,0);if(argc!=4)return 2;wcscpy(repo,argv[1]);wcscpy(linux_repo,argv[2]);wcscpy(conflict,argv[3]);SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);test_git_status_windows_and_parser();test_git_diff_staged_unstaged_deletion_binary();test_git_native_linux_raw_names_and_worktrees();test_git_conflicts_errors_and_environment();test_git_windows_recreated_working_files();test_git_native_recreated_working_files();test_git_panel_filters_lifecycle_and_pixels();printf("%d passed, %d failed; 7 Git selectors\n",passed,failed);return failed?1:0;}
